1	package com.loja.checkout.dominio.checkout;
2	
3	import com.loja.checkout.api.ItemRequest;
4	import com.loja.checkout.api.PedidoRequest;
5	import com.loja.checkout.api.ResumoResponse;
6	import com.loja.checkout.dominio.clube.NivelClube;
7	import com.loja.checkout.dominio.clube.NivelClubeRegistro;
8	import com.loja.checkout.dominio.cupom.Cupom;
9	import com.loja.checkout.dominio.cupom.CupomRegistro;
10	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
11	import com.loja.checkout.dominio.entrega.ModalidadeEntregaRegistro;
12	import com.loja.checkout.dominio.pagamento.FormaPagamento;
13	import com.loja.checkout.dominio.pagamento.FormaPagamentoRegistro;
14	import com.loja.checkout.dominio.pagamento.ResultadoPagamento;
15	import com.loja.checkout.dominio.seguro.Seguro;
16	import com.loja.checkout.infra.CheckoutException;
17	import org.springframework.stereotype.Service;
18	
19	import java.math.BigDecimal;
20	import java.math.RoundingMode;
21	import java.util.List;
22	
23	@Service
24	public class ServicoCheckout {
25	
26	    public ResumoResponse calcular(PedidoRequest pedido) {
27	        // 1. Valida itens
28	        validarItens(pedido.itens());
29	
30	        // Calcula subtotal e peso total agora que itens são válidos
31	        BigDecimal subtotalProdutos = calcularSubtotal(pedido.itens());
32	        double pesoTotalKg = calcularPesoTotal(pedido.itens());
33	
34	        // 2. Valida nível do clube
35	        NivelClube clube = NivelClubeRegistro.buscar(pedido.nivelClube());
36	
37	        // 3. Valida região
38	        Seguro.validarRegiao(pedido.regiao());
39	
40	        // 4+5. Valida modalidade (existência e disponibilidade)
41	        ModalidadeEntrega modalidade = ModalidadeEntregaRegistro.buscar(pedido.modalidadeEntrega());
42	        modalidade.validarDisponibilidade(pesoTotalKg);
43	
44	        // 6+7. Valida cupom (existência e aplicabilidade), se informado
45	        Cupom cupom = null;
46	        if (pedido.cupom() != null && !pedido.cupom().isBlank()) {
47	            cupom = CupomRegistro.buscar(pedido.cupom());
48	            cupom.validarAplicabilidade(subtotalProdutos);
49	        }
50	
51	        // 8+9. Valida forma de pagamento (existência e parcelas)
52	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
53	        FormaPagamento formaPagamento = FormaPagamentoRegistro.buscar(pedido.formaPagamento());
54	        formaPagamento.validarParcelas(parcelas);
55	
56	        // Calcula frete: OURO isenta
57	        BigDecimal frete = clube.isentaFrete()
58	                ? BigDecimal.ZERO.setScale(2)
59	                : modalidade.calcularFrete(pesoTotalKg);
60	
61	        // Calcula desconto do cupom
62	        BigDecimal descontoCupom = cupom != null
63	                ? cupom.calcularDesconto(subtotalProdutos, frete, pedido.itens())
64	                : BigDecimal.ZERO.setScale(2);
65	
66	        // Calcula seguro (sempre sobre subtotalProdutos, sem desconto e sem frete)
67	        BigDecimal seguro = Seguro.calcular(pedido.regiao(), subtotalProdutos);
68	
69	        // Total antes do pagamento
70	        BigDecimal total = subtotalProdutos
71	                .subtract(descontoCupom)
72	                .add(frete)
73	                .add(seguro);
74	
75	        // 10. Valida disponibilidade da forma de pagamento com o total calculado
76	        formaPagamento.validarDisponibilidade(total);
77	
78	        // Aplica forma de pagamento
79	        ResultadoPagamento resultado = formaPagamento.calcular(total, parcelas);
80	
81	        // Crédito e brinde são calculados sobre subtotalProdutos (sem desconto e sem frete)
82	        BigDecimal credito = clube.calcularCredito(subtotalProdutos);
83	        boolean brinde = clube.ganhabrinde(subtotalProdutos);
84	
85	        return new ResumoResponse(
86	                subtotalProdutos,
87	                descontoCupom,
88	                frete,
89	                modalidade.prazoEntregaDias(),
90	                seguro,
91	                resultado.ajustePagamento(),
92	                resultado.totalFinal(),
93	                resultado.parcelas(),
94	                resultado.valorParcela(),
95	                credito,
96	                brinde
97	        );
98	    }
99	
100	    private void validarItens(List<ItemRequest> itens) {
101	        if (itens == null || itens.isEmpty()) {
102	            throw new CheckoutException("PEDIDO_INVALIDO");
103	        }
104	        for (ItemRequest item : itens) {
105	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0) {
106	                throw new CheckoutException("PEDIDO_INVALIDO");
107	            }
108	            if (item.quantidade() == null || item.quantidade() <= 0) {
109	                throw new CheckoutException("PEDIDO_INVALIDO");
110	            }
111	            if (item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
112	                throw new CheckoutException("PEDIDO_INVALIDO");
113	            }
114	        }
115	    }
116	
117	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
118	        return itens.stream()
119	                .map(i -> i.precoUnitario()
120	                        .multiply(BigDecimal.valueOf(i.quantidade()))
121	                        .setScale(2, RoundingMode.HALF_EVEN))
122	                .reduce(BigDecimal.ZERO, BigDecimal::add);
123	    }
124	
125	    private double calcularPesoTotal(List<ItemRequest> itens) {
126	        return itens.stream()
127	                .mapToDouble(i -> i.pesoKg().doubleValue() * i.quantidade())
128	                .sum();
129	    }
130	}
