5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	public class PagamentoCartao implements FormaPagamento {
10	
11	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
12	    private static final int PARCELAS_SEM_JUROS = 3;
13	
14	    @Override
15	    public void validarParcelas(int parcelas) {
16	        if (parcelas < 1 || parcelas > 12) {
17	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
18	        }
19	    }
20	
21	    @Override
22	    public void validarDisponibilidade(BigDecimal total) {
23	        // sem restrição
24	    }
25	
26	    @Override
27	    public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
28	        if (parcelas <= PARCELAS_SEM_JUROS) {
29	            BigDecimal valorParcela = total.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
30	            return new ResultadoPagamento(BigDecimal.ZERO.setScale(2), total, parcelas, valorParcela);
31	        }
32	
33	        // Tabela Price: parcela = total × taxa / (1 − (1 + taxa)^−n)
34	        double r = TAXA_MENSAL.doubleValue();
35	        double fator = 1.0 - Math.pow(1.0 + r, -parcelas);
36	        BigDecimal valorParcela = total.multiply(TAXA_MENSAL)
37	                .divide(BigDecimal.valueOf(fator), 10, RoundingMode.HALF_EVEN)
38	                .setScale(2, RoundingMode.HALF_EVEN);
39	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
40	        BigDecimal ajuste = totalFinal.subtract(total);
41	        return new ResultadoPagamento(ajuste, totalFinal, parcelas, valorParcela);
42	    }
43	}
