        mvc.perform(post("/checkout/resumo")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"itens":[{"nome":"X","precoUnitario":10.00,"quantidade":1,"pesoKg":0.5}],
                                 "modalidadeEntrega":"EXPRESSA","cupom":"FAKE","formaPagamento":"PIX",
                                 "parcelas":1,"nivelClube":"BRONZE","regiao":"SUL"}
                                """))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.erro").value("CUPOM_INVALIDO"));
    }

